"""FMUProblem on interactive FMUs generated by omc --handGuidedTearing --interactiveFMU
from testsuite/simulation/modelica/tearing/HGTInteractive.mo.

omc is taken from $OMC, the CMake build of this repository (build_cmake), or the
PATH; the tests are skipped without omc or FMPy."""

import math
import os
import shutil
import subprocess
import zipfile

import pytest

pytest.importorskip("fmpy")

from omsteady import FMUProblem, Solver, HoldBalanceError, StructuralSingularityError
from omsteady.fmu import parse_model_description

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
MODELS = os.path.join(ROOT, "testsuite", "simulation", "modelica", "tearing", "HGTInteractive.mo")


def _find_omc():
    candidates = [os.environ.get("OMC"),
                  os.path.join(ROOT, "build_cmake", "install_cmake", "bin", "omc"),
                  shutil.which("omc")]
    return next((c for c in candidates if c and os.path.isfile(c)), None)


OMC = _find_omc()
pytestmark = pytest.mark.skipif(OMC is None, reason="omc not found")


@pytest.fixture(scope="session")
def fmus(tmp_path_factory):
    """Builds the interactive FMUs once, returns {model: path}."""
    work = tmp_path_factory.mktemp("fmus")
    models = ["TwoEq", "TwoBlocks", "Plant"]
    script = ['loadFile("%s"); getErrorString();' % MODELS.replace("\\", "/"),
              'setCommandLineOptions("--handGuidedTearing --interactiveFMU"); getErrorString();']
    for m in models:
        script.append('buildModelFMU(HGTInteractive.%s, version = "2.0", fmuType = "me", fileNamePrefix = "%s"); getErrorString();' % (m, m))
    (work / "build.mos").write_text("\n".join(script) + "\n")
    out = subprocess.run([OMC, "build.mos"], cwd=work, capture_output=True, text=True, timeout=900)
    paths = {m: str(work / (m + ".fmu")) for m in models}
    missing = [m for m, p in paths.items() if not os.path.isfile(p)]
    assert not missing, "omc did not build %s:\n%s%s" % (missing, out.stdout, out.stderr)
    return paths


def _model_description(path):
    with zipfile.ZipFile(path) as z:
        return parse_model_description(z.read("modelDescription.xml").decode("utf-8"))


# --- the FMU interface --------------------------------------------------------------

def test_interface(fmus):
    m = _model_description(fmus["TwoEq"])
    assert [i.name for i in m.iteration_variables] == ["iter_0", "iter_1"]
    assert [r.name for r in m.residuals] == ["res_0", "res_1"]
    x, T = (i.variable for i in m.iteration_variables)
    assert (x.causality, x.description, x.start) == ("input", "x", "1.0")
    assert (T.description, T.nominal) == ("T", 100.0)
    assert all(r.variable.causality == "output" for r in m.residuals)
    assert m.residuals[0].variable.description.startswith("0.0 = 120.0 * x")
    assert "LongEq" in m.residuals[0].variable.description
    # the hold parameters are bound to the parameter expressions: calculated parameters
    assert [i.hold.causality for i in m.iteration_variables + m.residuals] == ["calculatedParameter"] * 4
    # each residual depends on both iteration variables
    assert m.dependencies == [{0, 1}, {0, 1}]


def test_literal_hold_is_a_parameter(fmus):
    m = _model_description(fmus["TwoBlocks"])
    # e2 has no hold: res_1_hold is a parameter that can be set directly
    assert m.residuals[1].hold.causality == "parameter"
    assert m.residuals[1].hold.start == "false"
    # e1 only depends on p
    assert m.dependencies == [{0}, {0, 1}]


def test_bounds_start_and_residual_nominal(fmus):
    m = _model_description(fmus["Plant"])
    p_mid, mm = (i.variable for i in m.iteration_variables)
    assert p_mid.description == "p_mid" and p_mid.start == "5.0" and p_mid.max == 100.0
    assert mm.description == "m" and mm.min == 0.0
    assert m.residuals[0].variable.nominal == 10.0


def test_residuals_at_known_solution(fmus):
    p = FMUProblem(fmus["TwoEq"])
    # the solution of the FunctionProblem version of the model
    from models import two_eq_steady_state_para_hold
    f = two_eq_steady_state_para_hold()
    assert Solver(f).solve().success
    p.set("x", f.get("x"))
    p.set("T", f.get("T"))
    assert max(abs(r) for r in p.evaluate_residuals()) < 1e-8
    p.set("x", 0.5)
    p.set("T", 300.0)
    r = p.evaluate_residuals()
    k = 0.12 * math.exp(12581 * (300 - 298) / (298 * 300))
    assert r[0] == pytest.approx(0 - (120 * 0.5 - 75 * k * 0.5), rel=1e-10)
    assert r[1] == pytest.approx(0 - (-0.5 * (873 - 300) + 11.0 * 0), abs=1e-10)
    p.terminate()


# --- the official example, doc/HGT_interactive_fmu_phase1.md section 6 ------------

def test_official_example(fmus):
    p = FMUProblem(fmus["TwoEq"])
    p.printInfo("all")

    sol = Solver(p).solve()
    assert sol.success, sol.message
    x, T = p.get(["x", "T"])
    assert x == pytest.approx(0.963868, abs=1e-6) and T == pytest.approx(346.16370, abs=1e-4)

    p.set("testHold1", True)               # T fixed, LongEq dropped
    p.set("T", 330.0)
    sol = Solver(p).solve()
    assert sol.success, sol.message
    assert sol.held_variables == [1] and sol.held_residuals == [0]
    x, T = p.get(["x", "T"])
    assert T == 330.0 and x == pytest.approx(11 * 30 / 543, abs=1e-8)

    p.set("testHold1", False)
    p.set("testHold2", True)               # x fixed, LongEq2 dropped
    p.set("x", 0.8)
    sol = Solver(p).solve()
    assert sol.success, sol.message
    x, T = p.get(["x", "T"])
    assert x == 0.8 and T == pytest.approx(328.98763, abs=1e-4)

    p.set("testHold2", False)
    p.holdIterationVariables(["x"])        # only a variable: unbalanced
    with pytest.raises(HoldBalanceError):
        Solver(p).solve()
    p.terminate()


def test_hold_parameters_are_read_from_the_fmu(fmus):
    p = FMUProblem(fmus["TwoEq"])
    assert [list(h) for h in p.parametric_hold()] == [[False, False], [False, False]]
    p.set("testHold1", True)
    assert [list(h) for h in p.parametric_hold()] == [[False, True], [True, False]]
    p.terminate()


def test_set_literal_hold_parameter(fmus):
    # without hold attributes the hold parameters are parameters: hold any
    # iteration variable without changing the model
    p = FMUProblem(fmus["Plant"])
    assert [i.hold.causality for i in p.model.iteration_variables + p.model.residuals] == ["parameter"] * 4
    p.set("iter_0_hold", True)             # hold p_mid
    p.set("res_0_hold", True)              # drop pipe1.m = m
    p.set("p_mid", 50.0)
    sol = Solver(p).solve()
    assert sol.success, sol.message
    assert p.get("m") == pytest.approx(21.0, abs=1e-8)
    p.terminate()


def test_names(fmus):
    p = FMUProblem(fmus["TwoEq"])
    assert [p.variable_index(n) for n in ("x", "iter_1", 0)] == [0, 1, 0]
    assert [p.residual_index(n) for n in ("LongEq", "LongEq2", "res_1")] == [0, 1, 1]
    p.terminate()


# --- across blocks -----------------------------------------------------------------------

@pytest.mark.parametrize("blocks", [False, True])
def test_two_blocks(fmus, blocks):
    p = FMUProblem(fmus["TwoBlocks"])
    sol = Solver(p, blocks=blocks).solve()
    assert sol.success, sol.message
    assert p.get(["p", "m"]) == pytest.approx([2.0, 1.0], abs=1e-8)

    p.set("design", True)                  # hold m, drop e1: e2 determines p
    p.set("m", 2.0)
    sol = Solver(p, blocks=blocks).solve()
    assert sol.success, sol.message
    assert p.get("p") == pytest.approx(5.0, abs=1e-8)
    p.terminate()


def test_two_blocks_reverse_hold_is_structurally_singular(fmus):
    p = FMUProblem(fmus["TwoBlocks"])
    p.holdIterationVariables(["p"])
    p.holdResiduals(["e2"])
    with pytest.raises(StructuralSingularityError):
        Solver(p).solve()
    p.terminate()


def test_parameter_change_keeps_the_iteration_values(fmus):
    p = FMUProblem(fmus["TwoBlocks"])
    assert Solver(p).solve().success
    p.set("k", 4.0)                        # re-initializes the FMU
    assert p.get(["p", "m"]) == pytest.approx([2.0, 1.0], abs=1e-8)
    assert Solver(p).solve().success
    assert p.get("m") == pytest.approx(2.0, abs=1e-8)
    p.terminate()


def test_plant(fmus):
    p = FMUProblem(fmus["Plant"])
    sol = Solver(p).solve()
    assert sol.success, sol.message
    p_mid, m = p.get(["p_mid", "m"])
    assert p_mid == pytest.approx(409 / 13, abs=1e-6)
    assert m == pytest.approx(2 * math.sqrt(100 - 409 / 13), abs=1e-6)
    p.terminate()
